function guessPool(cat,round,difficulty='mixed'){const c=CATS[cat];if(!c)return[];if(difficulty!=='mixed')return c[difficulty]||c.easy||[];const levels=['easy','medium','hard'];return c[levels[(Math.max(1,round)-1)%3]]||c.easy||[]}
