function marketSequence(max){const base=[];for(let i=1;i<=max;i++){if(i===3||i===6||i%7===0)base.push('secret');else if(i===5||i%7===5)base.push('doubleEvent');else base.push('normal')}return base}
function marketPickQuestion(g){let choices=marketQs.map((_,i)=>i).filter(i=>!g.used.includes(i));if(!choices.length){g.used=[];choices=marketQs.map((_,i)=>i)}const idx=choices[Math.floor(Math.random()*choices.length)];g.used.push(idx);return marketQs[idx]}
function marketPublic(g){const players=(g.players||[]).map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',online:p.online!==false,ready:p.ready!==false,score:g.scores[p.id]||0,insuranceUsed:!!g.insuranceUsed[p.id],doubleUsed:!!g.doubleUsed[p.id],withdrawn:!!g.withdrawn[p.id]}));const out={type:'market',code:g.code,mode:'players',phase:g.phase,round:g.round,maxRounds:g.maxRounds,question:g.question,points:g.roundValue,baseValue:g.baseValue,eventMultiplier:g.eventMultiplier,roundType:g.roundType,auctionUntil:g.auctionUntil,executeUntil:g.executeUntil,highestBid:g.highestBid,highestBidderId:g.highestBidderId,activeBidders:g.activeBidders,withdrawn:g.withdrawn,secretSubmitted:Object.keys(g.secretBids).length,secretTotal:g.players.filter(p=>p.online!==false).length,revealedBids:g.revealedBids,current:g.current?{...g.current}:null,judgeId:g.judgeId,correctCount:g.correctCount,wrongCount:g.wrongCount,roundInsurance:g.roundInsurance,roundDouble:g.roundDouble,scores:g.scores,players,history:g.history.slice(-10),config:g.config,isHost:false,myPlayerId:null};return out}
function broadcastMarket(g){const room=io.sockets.adapter.rooms.get(g.code);if(!room)return;for(const sid of room){const sock=io.sockets.sockets.get(sid);if(!sock)continue;const out=marketPublic(g);out.isHost=sock.data?.pid===g.hostId;out.myPlayerId=sock.data?.pid||null;out.myBid=g.secretBids[sock.data?.pid]||null;out.myWithdrawn=!!g.withdrawn[sock.data?.pid];out.myInsurance=!!g.insuranceUsed[sock.data?.pid];out.myDouble=!!g.doubleUsed[sock.data?.pid];out.isJudge=sock.data?.pid===g.judgeId;io.to(sid).emit('state',out)}}
function marketChooseJudge(g,winnerId){const others=g.players.filter(p=>p.online!==false&&p.id!==winnerId);if(!others.length)return null;return others[Math.floor(Math.random()*others.length)].id}
function marketStart(g){if(g.round>=g.maxRounds){g.phase='finished';g.finishedAt=Date.now();broadcastMarket(g);return}const q=marketPickQuestion(g);g.round++;g.questionData=q;g.question=q.q;g.baseValue=Math.max(100,Number(g.config?.baseValue)||1000);g.roundType=g.eventSequence[g.round-1]||'normal';g.eventMultiplier=g.roundType==='doubleEvent'?2:1;g.roundValue=g.baseValue*g.eventMultiplier;g.highestBid=0;g.highestBidderId=null;g.activeBidders=g.players.filter(p=>p.online!==false).map(p=>p.id);g.withdrawn={};g.secretBids={};g.revealedBids=[];g.current=null;g.judgeId=null;g.correctCount=0;g.wrongCount=0;g.roundInsurance=false;g.roundDouble=false;g.auctionUntil=0;g.executeUntil=0;
 const begin=()=>{if(g.roundType==='doubleEvent'){g.phase='event';broadcastMarket(g);const r=g.round;setTimeout(()=>{if(g.phase==='event'&&g.round===r){g.roundType='normal';g.eventMultiplier=2;g.roundValue=g.baseValue*2;marketBeginAuction(g)}},2600)}else marketBeginAuction(g)};begin()}
function marketBeginAuction(g){g.phase=g.roundType==='secret'?'secretAuction':'auction';g.auctionUntil=Date.now()+Math.max(8,Number(g.config?.bidTimeSec)||20)*1000;broadcastMarket(g);const until=g.auctionUntil,round=g.round;setTimeout(()=>{if(g.phase==='auction'&&g.round===round&&g.auctionUntil===until)marketResolveNormal(g);else if(g.phase==='secretAuction'&&g.round===round&&g.auctionUntil===until)marketResolveSecret(g)},(Math.max(8,Number(g.config?.bidTimeSec)||20)*1000)+100)}
function marketResolveNormal(g){const active=g.activeBidders.filter(id=>!g.withdrawn[id]&&g.players.some(p=>p.id===id&&p.online!==false));g.activeBidders=active;g.auctionUntil=0;if(!g.highestBidderId&&active.length===1){g.highestBidderId=active[0];g.highestBid=1}if(!g.highestBidderId||g.highestBid<1){return marketRoundNoWinner(g,'انتهى المزاد بدون مزايدة')}g.current={id:g.highestBidderId,name:g.players.find(p=>p.id===g.highestBidderId)?.name||'لاعب',bid:g.highestBid,insurance:!!g.insuranceUsed[g.highestBidderId],double:!!g.doubleUsed[g.highestBidderId]};marketStartExecution(g)}
function marketResolveSecret(g){g.auctionUntil=0;const entries=Object.entries(g.secretBids).map(([id,b])=>({id,b:Number(b)||0})).filter(x=>x.b>0&&g.players.some(p=>p.id===x.id&&p.online!==false));entries.sort((a,b)=>b.b-a.b);g.revealedBids=entries.map(x=>({id:x.id,name:g.players.find(p=>p.id===x.id)?.name||'لاعب',bid:x.b}));if(!entries.length)return marketRoundNoWinner(g,'لم يقدم أحد مزايدة');const winner=entries[0];g.highestBid=winner.b;g.highestBidderId=winner.id;g.current={id:winner.id,name:g.players.find(p=>p.id===winner.id)?.name||'لاعب',bid:winner.b,insurance:!!g.insuranceUsed[winner.id],double:!!g.doubleUsed[winner.id]};g.phase='reveal';broadcastMarket(g);const r=g.round;setTimeout(()=>{if(g.phase==='reveal'&&g.round===r)marketStartExecution(g)},2200)}
function marketRoundNoWinner(g,reason){g.history.push({round:g.round,question:g.question,result:'لا فائز',reason,delta:0,roundValue:g.roundValue});g.phase='results';g.current=null;g.judgeId=null;broadcastMarket(g);if(g.championParent&&g.round>=g.maxRounds){setTimeout(()=>{if(g.phase==='results'&&g.championParent){g.phase='finished';g.finishedAt=Date.now();broadcastMarket(g)}},1800)}}
function marketStartExecution(g){if(!g.current)return marketRoundNoWinner(g,'لا يوجد فائز');g.judgeId=marketChooseJudge(g,g.current.id);if(!g.judgeId)return marketRoundNoWinner(g,'لا يوجد حكم متاح');g.correctCount=0;g.wrongCount=0;g.phase='execute';g.executeUntil=Date.now()+Math.max(10,Number(g.config?.executeTimeSec)||30)*1000;broadcastMarket(g);const until=g.executeUntil,round=g.round,winner=g.current.id;setTimeout(()=>{if(g.phase==='execute'&&g.round===round&&g.executeUntil===until&&g.current?.id===winner)marketResolveExecution(g,false,'انتهى الوقت')},(Math.max(10,Number(g.config?.executeTimeSec)||30)*1000)+100)}
function marketResolveExecution(g,success,reason){if(!g.current)return;const p=g.current.id;const value=g.roundValue*(g.current.double?2:1);let delta;if(success)delta=value;else delta=g.current.insurance?0:-value;g.scores[p]=(g.scores[p]||0)+delta;g.history.push({round:g.round,question:g.question,player:g.current.name,required:g.current.bid,correct:g.correctCount,wrong:g.wrongCount,result:success?'نجح':'خسر',delta,value,insurance:g.current.insurance,double:g.current.double});g.phase='results';g.executeUntil=0;broadcastMarket(g);if(g.championParent&&g.round>=g.maxRounds){setTimeout(()=>{if(g.phase==='results'&&g.championParent){g.phase='finished';g.finishedAt=Date.now();broadcastMarket(g)}},1800)}}
