function millionPick(g,st,level){const all=[...(g.questions||[]),...MILLION_EXTRA];let pool=all.filter(q=>q.level===level&&!st.used.includes(q.q));if(!pool.length){const levelWords=new Set(all.filter(q=>q.level===level).map(q=>q.q));st.used=st.used.filter(x=>!levelWords.has(x));pool=all.filter(q=>q.level===level)}return pool[Math.floor(Math.random()*pool.length)]}
