function broadcast(g){if(g.phase==='finished'&&!g.finishedAt)g.finishedAt=Date.now();if(g.type==='mafia'){broadcastMafia(g);return}if(g.type==='guess'){broadcastGuess(g);persistGames();return}if(g.type==='bomb'){broadcastBomb(g);persistGames();return}if(g.type==='faceoff'){broadcastFaceoff(g);return}if(g.type==='liar'){broadcastLiar(g);persistGames();return}if(g.type==='champion'){broadcastChampion(g);return}if(g.type==='draw'){broadcastDraw(g);return}io.to(g.code).emit('state',pub(g));persistGames()}
function bombPublicState(g,sid){const isHost=io.sockets.sockets.get(sid)?.data?.role==='presenter';const answers=(g.answers||[]).map(a=>isHost||a.revealed?{text:a.text,points:a.points,trap:a.revealed?a.trap:undefined,revealed:a.revealed,awarded:a.awarded}:({text:'',points:0,revealed:false,awarded:false}));const teams=(g.teams||[]).map(t=>({id:t.id,name:t.name,score:t.score,players:(t.players||[]).map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',online:p.online!==false,ready:p.ready!==false}))}));const out={...g,isHost:io.sockets.sockets.get(sid)?.data?.pid===g.hostId,answers,teams,players:(g.players||[]).map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',team:p.team,online:p.online!==false,ready:p.ready!==false})),scores:g.scores,questionStats:{listed:(g.answers||[]).length,traps:(g.answers||[]).filter(a=>a.trap).length,extra:(g.extra||[]).length,round:g.round},contentTotal:bombAllQs.length};if(!isHost){out.extra=undefined;out.used=undefined}return out}
function emitBombState(g,sid){if(g&&sid&&io.sockets.sockets.has(sid))io.to(sid).emit('state',bombPublicState(g,sid))}
function broadcastBomb(g){const room=io.sockets.adapter.rooms.get(g.code);if(!room)return;for(const sid of room)emitBombState(g,sid)}
function emitBombStateToSocket(g,s){if(!g||g.type!=='bomb'||!s)return;const isHost=s.data?.role==='presenter';const answers=(g.answers||[]).map(a=>isHost||a.revealed?{text:a.text,points:a.points,trap:a.revealed?a.trap:undefined,revealed:a.revealed,awarded:a.awarded}:{text:'',points:0,revealed:false,awarded:false});const teams=(g.teams||[]).map(t=>({id:t.id,name:t.name,score:t.score,players:(t.players||[]).map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',online:p.online!==false,ready:p.ready!==false}))}));const out={...g,isHost:io.sockets.sockets.get(sid)?.data?.pid===g.hostId,answers,teams,players:(g.players||[]).map(p=>({id:p.id,name:p.name,avatar:p.avatar||'',team:p.team,online:p.online!==false,ready:p.ready!==false})),scores:g.scores,questionStats:{listed:(g.answers||[]).length,traps:(g.answers||[]).filter(a=>a.trap).length,extra:(g.extra||[]).length,round:g.round},contentTotal:bombAllQs.length};if(!isHost){out.extra=undefined;out.used=undefined}s.emit('state',out)}
function broadcastGuess(g){const room=io.sockets.adapter.rooms.get(g.code);if(!room)return;for(const sid of room){const sock=io.sockets.sockets.get(sid);const viewer=sock?.data?.pid;const out={...g,secret:undefined,players:g.players.map(p=>({...p,revealedWord:g.revealedBy?.[viewer]?.[p.id]||null,guessed:!!g.guessed[p.id],score:g.scores[p.id]||0}))};io.to(sid).emit('state',out)}}
function broadcastMillion(g){const room=io.sockets.adapter.rooms.get(g.code);if(!room)return;for(const sid of room){const sock=io.sockets.sockets.get(sid);if(sock)io.to(sid).emit('state',pubMillion(g,sock))}persistGames()}
function addPlayer(g,s,name,team,token,avatar){const cleanToken=String(token||'');const existing=cleanToken&&g.players.find(p=>p.sessionToken===cleanToken);if(existing){return restorePlayerIdentity(g,existing,s,avatar)}if(g.players.some(p=>p.socketId===s.id&&p.online!==false))return g.players.find(p=>p.socketId===s.id);let chosen=team==='B'?'B':'A';const av=String(avatar||'').startsWith('data:image/')?String(avatar).slice(0,180000):'';const p={id:'P'+crypto.randomBytes(10).toString('hex'),name:String(name||'').trim().slice(0,24)||'لاعب',avatar:av,team:chosen,sessionToken:sessionToken(),online:true,disconnectedAt:null,socketId:s.id,ready:true};g.players.push(p);if(g.type==='family'||g.type==='bomb'||g.type==='faceoff')g.teams.find(t=>t.id===p.team).players.push(p);if(g.type==='family'||g.type==='bomb'){const tm=g.teams.find(t=>t.id===p.team);if(tm&&!tm.captainId)tm.captainId=p.id;}if(g.type==='guess')g.scores[p.id]=0;if(g.type==='bomb')g.scores[p.id]=0;if(g.type==='million')millionInitPlayer(g,p);s.join(g.code);s.data={game:g.code,role:'player',pid:p.id,team:p.team,sessionToken:p.sessionToken};persistGames();return p}
function lobbyReady(g){return (g.players||[]).filter(p=>p.online!==false).every(p=>p.ready!==false)}
function startFF(g,incrementRound=true){let choices=g.bank.map((_,i)=>i).filter(i=>!g.usedQuestionIndexes.includes(i));if(!choices.length){g.usedQuestionIndexes=[];choices=g.bank.map((_,i)=>i)}const idx=choices[Math.floor(Math.random()*choices.length)];g.usedQuestionIndexes.push(idx);const q=g.bank[idx];if(incrementRound||g.currentRound<1)g.currentRound++;g.questionIndex=idx;g.question=q.q;g.answers=q.a.map(x=>({text:x[0],points:x[1],revealed:false,awarded:false}));g.phase='countdown';g.countdownUntil=Date.now()+3000;g.lock=null;g.answerLock=null;g.teams.forEach(t=>{t.strikes=0;t.doubleActive=false;t.doublePlayer=''});broadcast(g);const round=g.currentRound,until=g.countdownUntil;setTimeout(()=>{if(g.phase==='countdown'&&g.currentRound===round&&g.countdownUntil===until&&Date.now()>=until){g.phase='question';g.countdownUntil=0;broadcast(g)}},3100)}
function ffHost(s,g){return s.data?.game===g.code&&s.data.role==='presenter'&&['1','2'].includes(g.mode)}
