// Stage 6 content buffer: keep enough cards available for time-based rounds.
// We intentionally avoid immediate repeats and cycle the existing curated images when a category is exhausted.
for (const cat of Object.values(faceoffCategories)) {
  const base = Array.isArray(cat.items) ? cat.items.slice() : [];
  if (!base.length) continue;
  const target = cat.name === 'لاعبو كرة القدم' || cat.name === 'مغنين' ? 30 : 18;
  let i = 0;
  while (cat.items.length < target) {
    const src = base[i % base.length];
    cat.items.push([src[0], src[1]]);
    i++;
  }
}

