function liarStartRound(g){if(g.round>=g.maxRounds){g.phase='finished';g.winnerText='انتهت الجولات — استمتعتم باللعبة!';g.finishedAt=Date.now();broadcastLiar(g);return}const pair=liarQs[Math.floor(Math.random()*liarQs.length)],pool=g.players.filter(p=>p.online!==false);if(pool.length<4)return;pool.forEach(p=>{if(g.scores[p.id]==null)g.scores[p.id]=0});g.round++;g.question=pair[0];g.liarQuestion=pair[1];g.liarId=pool[Math.floor(Math.random()*pool.length)].id;g.answers={};g.votes={};g.caught=false;g.voted=false;g.phase='answer';g.phaseUntil=Date.now()+25000;broadcastLiar(g);const until=g.phaseUntil;setTimeout(()=>{if(g.phase==='answer'&&g.phaseUntil===until)liarStartDiscussion(g)},25100)}
